127	// GetUserByPATHash finds a user by PAT hash.
128	func (s *Store) GetUserByPATHash(ctx context.Context, tokenHash string) (*PATQueryResult, error) {
129		result, err := s.driver.GetUserByPATHash(ctx, tokenHash)
130		if err != nil {
131			return nil, err
132		}
133	
134		// Fetch user info
135		user, err := s.GetUser(ctx, &FindUser{ID: &result.UserID})
136		if err != nil {
137			return nil, err
138		}
139		if user == nil {
140			return nil, errors.New("user not found for PAT")
141		}
142		result.User = user
143	
144		return result, nil
145	}
