328	// AddUserWebhook adds a new webhook for the user.
329	func (s *Store) AddUserWebhook(ctx context.Context, userID int32, webhook *storepb.WebhooksUserSetting_Webhook) error {
330		existingWebhooks, err := s.GetUserWebhooks(ctx, userID)
331		if err != nil {
332			return err
333		}
334	
335		// Check if webhook already exists, update if it does
336		var updatedWebhooks []*storepb.WebhooksUserSetting_Webhook
337		webhookExists := false
338		for _, existing := range existingWebhooks {
339			if existing.Id == webhook.Id {
340				updatedWebhooks = append(updatedWebhooks, webhook)
341				webhookExists = true
342			} else {
343				updatedWebhooks = append(updatedWebhooks, existing)
344			}
345		}
346	
347		// If webhook doesn't exist, add it
348		if !webhookExists {
349			updatedWebhooks = append(updatedWebhooks, webhook)
350		}
351	
352		_, err = s.UpsertUserSetting(ctx, &storepb.UserSetting{
353			UserId: userID,
354			Key:    storepb.UserSetting_WEBHOOKS,
355			Value: &storepb.UserSetting_Webhooks{
356				Webhooks: &storepb.WebhooksUserSetting{
357					Webhooks: updatedWebhooks,
358				},
359			},
360		})
361	
362		return err
363	}
