468	func convertUserSettingToRaw(userSetting *storepb.UserSetting) (*UserSetting, error) {
469		raw := &UserSetting{
470			UserID: userSetting.UserId,
471			Key:    userSetting.Key,
472		}
473	
474		switch userSetting.Key {
475		case storepb.UserSetting_SHORTCUTS:
476			shortcutsUserSetting := userSetting.GetShortcuts()
477			value, err := protojson.Marshal(shortcutsUserSetting)
478			if err != nil {
479				return nil, err
480			}
481			raw.Value = string(value)
482		case storepb.UserSetting_GENERAL:
483			generalUserSetting := userSetting.GetGeneral()
484			value, err := protojson.Marshal(generalUserSetting)
485			if err != nil {
486				return nil, err
487			}
488			raw.Value = string(value)
489		case storepb.UserSetting_TAGS:
490			tagsUserSetting := userSetting.GetTags()
491			value, err := protojson.Marshal(tagsUserSetting)
492			if err != nil {
493				return nil, errors.Wrap(err, "marshal tags user setting")
494			}
495			raw.Value = string(value)
496		case storepb.UserSetting_REFRESH_TOKENS:
497			refreshTokensUserSetting := userSetting.GetRefreshTokens()
